def close_ticket(t):
    missing=[k for k in ['id','local','owner','evidence','accepted_by'] if not t.get(k)]
    if t['cost']>250 and not t.get('cost_approved_by'): missing.append('cost_approved_by')
    return dict(id=t['id'],requested_status='Zamknięte',result='BLOCKED' if missing else 'CLOSED',missing=missing)
fixtures=[dict(id='REP-DEMO-001',local='DEMO-01',owner='Asystent',cost=180,evidence='demo-confirmation-001',accepted_by='Właściciel'),dict(id='REP-DEMO-002',local='DEMO-02',owner='Asystent',cost=420,evidence='demo-confirmation-002',accepted_by='Właściciel'),dict(id='REP-DEMO-003',local='DEMO-03',owner='Asystent',cost=420,evidence='demo-confirmation-003',accepted_by='Właściciel',cost_approved_by='Właściciel')]
result=[close_ticket(t) for t in fixtures]
assert [r['result'] for r in result]==['CLOSED','BLOCKED','CLOSED']
assert result[1]['missing']==['cost_approved_by']
